use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::process::Command;

/// Path to the user's ATLAS home directory.
fn atlas_home() -> PathBuf {
    dirs::home_dir()
        .expect("could not determine home directory")
        .join(".atlas")
}

/// Check whether the `.env` file has been generated by the installer.
fn is_bootstrap_done() -> bool {
    atlas_home().join(".env").exists()
}

/// Check whether Docker is running (best-effort).
fn is_docker_running() -> bool {
    Command::new("docker")
        .args(["info"])
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

#[derive(Serialize, Deserialize, Clone)]
pub struct SystemInfo {
    pub os: String,
    pub arch: String,
    pub atlas_home: String,
    pub env_exists: bool,
    pub docker_running: bool,
    pub bootstrap_done: bool,
}

#[tauri::command]
fn get_system_info() -> SystemInfo {
    let env_exists = atlas_home().join(".env").exists();
    SystemInfo {
        os: std::env::consts::OS.to_string(),
        arch: std::env::consts::ARCH.to_string(),
        atlas_home: atlas_home().display().to_string(),
        env_exists,
        docker_running: is_docker_running(),
        bootstrap_done: is_bootstrap_done(),
    }
}

#[tauri::command]
fn run_bootstrap() -> Result<String, String> {
    // Look for the installer script next to the Tauri binary or in the
    // project root. The project root is determined by walking up from the
    // current executable.
    let exe_dir = std::env::current_exe()
        .map(|p| p.parent().map(|d| d.to_path_buf()))
        .ok()
        .flatten()
        .unwrap_or_else(|| PathBuf::from("."));

    // Candidates: <exe>/../install(.bat), <project>/install(.bat)
    let candidates: Vec<PathBuf> = if cfg!(windows) {
        vec![
            exe_dir.join("..").join("install.bat"),
            exe_dir.join("install.bat"),
        ]
    } else {
        vec![
            exe_dir.join("..").join("install"),
            exe_dir.join("install"),
        ]
    };

    let installer = candidates
        .iter()
        .find(|p| p.exists())
        .ok_or_else(|| {
            format!(
                "Installer script not found. Searched: {:?}",
                candidates
            )
        })?;

    let mut cmd = if cfg!(windows) {
        let mut c = Command::new("cmd");
        c.args(["/C", &installer.display().to_string()]);
        c
    } else {
        Command::new("sh")
    };
    cmd.arg(installer);

    let output = cmd
        .output()
        .map_err(|e| format!("Failed to run installer: {e}"))?;

    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).to_string())
    } else {
        Err(format!(
            "Installer failed (exit {:?}): {}",
            output.status.code(),
            String::from_utf8_lossy(&output.stderr)
        ))
    }
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_updater::Builder::new().build())
        .invoke_handler(tauri::generate_handler![get_system_info, run_bootstrap])
        .run(tauri::generate_context!())
        .expect("error while running ATLAS desktop");
}